/** Time is a dependency, so tests can freeze it. Epoch milliseconds. */
export interface Clock {
  now(): number;
}

/** Ids are generated by the infrastructure (Firestore auto ids, UUIDs). */
export interface IdGenerator {
  next(): string;
}

/** Who is performing an action. Every write is attributable. */
export interface Actor {
  readonly uid: string;
  readonly name: string;
}

/**
 * Unit of work. Use cases describe *what* should change as domain-level operations;
 * an adapter applies them atomically (a Firestore batch or transaction).
 */
export interface Writer<Op> {
  commit(bizId: string, ops: readonly Op[]): Promise<void>;
}

export const systemClock: Clock = { now: () => Date.now() };
